// Firebase for the extension, over REST: Manifest V3 forbids loading remote code,
// and the few calls we need are small. Same data and rules as the web and Mac apps.

// project keys and URLs: config.js, generated by scripts/configure.py (git-ignored)
import { CONFIG } from "./config.js";
export { CONFIG };

const DOCS = `https://firestore.googleapis.com/v1/projects/${CONFIG.projectId}/databases/(default)/documents`;

export class NotSignedIn extends Error {
  constructor() { super("Not signed in"); this.name = "NotSignedIn"; }
}

const pad = (n) => String(n).padStart(2, "0");
export const today = () => { const d = new Date(); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; };
export const rank = (n) => (typeof n.order === "number" ? n.order : Date.parse(n.created_at) || 0);

// ---------- session ----------

export async function getSession() {
  const { session } = await chrome.storage.local.get("session");
  return session || null;
}

async function setSession(session) {
  if (session) await chrome.storage.local.set({ session });
  else await chrome.storage.local.remove("session");
}

function claims(jwt) {
  let b64 = jwt.split(".")[1].replace(/-/g, "+").replace(/_/g, "/");
  b64 += "=".repeat((4 - (b64.length % 4)) % 4);
  return JSON.parse(atob(b64));
}

/** A valid ID token, refreshed from the stored refresh token when it is close to expiring. */
async function idToken() {
  const s = await getSession();
  if (!s) throw new NotSignedIn();
  if (s.idToken && s.expires > Date.now() + 60_000) return s.idToken;

  const res = await fetch(`https://securetoken.googleapis.com/v1/token?key=${CONFIG.apiKey}`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "refresh_token", refresh_token: s.refreshToken }),
  });
  if (res.status >= 400 && res.status < 500) { await setSession(null); throw new NotSignedIn(); }
  if (!res.ok) throw new Error(`Couldn’t reach Firebase (HTTP ${res.status})`);
  const body = await res.json();
  const c = claims(body.id_token);
  await setSession({
    refreshToken: body.refresh_token,
    uid: body.user_id,
    email: (c.email || "").toLowerCase(),
    name: c.name || c.email || "",
    photo: c.picture || "",
    idToken: body.id_token,
    expires: Date.now() + Number(body.expires_in) * 1000,
  });
  return body.id_token;
}

/** Google sign-in through the web app's /link page, which hands a refresh token back to this extension only. */
export async function signIn() {
  const back = chrome.identity.getRedirectURL("auth");
  const url = `${CONFIG.linkURL}?return=${encodeURIComponent(back)}`;
  const result = await chrome.identity.launchWebAuthFlow({ url, interactive: true });
  const token = new URLSearchParams(new URL(result).hash.slice(1)).get("refresh_token");
  if (!token) throw new Error("Sign-in didn’t return a token.");
  await setSession({ refreshToken: token, expires: 0 });
  await idToken();
  return getSession();
}

export const signOut = async () => {
  await chrome.storage.local.remove("profileSavedAt");
  await setSession(null);
};

// ---------- Firestore REST ----------

function enc(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === "string") return { stringValue: v };
  if (typeof v === "boolean") return { booleanValue: v };
  if (Number.isInteger(v)) return { integerValue: String(v) };
  if (typeof v === "number") return { doubleValue: v };
  if (Array.isArray(v)) return { arrayValue: v.length ? { values: v.map(enc) } : {} };
  if (v instanceof Date) return { timestampValue: v.toISOString() };
  if (typeof v === "object") return { mapValue: { fields: encFields(v) } };
  return { nullValue: null };
}

function dec(f) {
  if ("stringValue" in f) return f.stringValue;
  if ("integerValue" in f) return Number(f.integerValue);
  if ("doubleValue" in f) return f.doubleValue;
  if ("booleanValue" in f) return f.booleanValue;
  if ("arrayValue" in f) return (f.arrayValue.values || []).map(dec);
  return null;
}

const encFields = (obj) => Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, enc(v)]));
const fromDoc = (d) => ({ id: d.name.split("/").pop(), ...Object.fromEntries(Object.entries(d.fields || {}).map(([k, v]) => [k, dec(v)])) });

async function api(method, path, body) {
  const res = await fetch(`${DOCS}${path}`, {
    method,
    headers: { Authorization: `Bearer ${await idToken()}`, "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error?.message || `HTTP ${res.status}`);
  return data;
}

// ---------- notes ----------

// same rules as web/notes-model.js: "- item" / "[ ] item" / "[x] item" lines become a checklist
const LIST_LINE = /^\s*(?:[-*•]\s*)?\[\s*([xX✓]?)\s*\]\s+(.+)$|^\s*[-*•]\s+(.+)$/;
function parseChecklist(text) {
  const items = [];
  const rest = [];
  for (const line of text.split("\n")) {
    const m = line.match(LIST_LINE);
    if (m) items.push({ id: Math.random().toString(36).slice(2, 10), text: (m[2] || m[3]).trim().slice(0, 500), done: Boolean(m[1]) });
    else if (line.trim()) rest.push(line.trim());
  }
  if (!items.length) return { content: text.trim(), checklist: [] };
  return { content: rest.join("\n") || "Checklist", checklist: items.slice(0, 100) };
}

/** Bumps users/{uid}.notesCreated for the users dashboard; never fails the note itself. */
function countNoteCreated(uid) {
  return api("POST", ":commit", {
    writes: [{
      transform: {
        document: `projects/${CONFIG.projectId}/databases/(default)/documents/users/${uid}`,
        fieldTransforms: [{ fieldPath: "notesCreated", increment: { integerValue: "1" } }],
      },
    }],
  }).catch(() => {});
}

/**
 * Saves a note for a day. `shot` (optional) is a screenshot: { full, thumb, width, height }, where
 * `full`/`thumb` are JPEG data: URLs. The full image goes to qn_attachments; the note keeps the thumbnail.
 */
export async function addNote(content, noteDate = today(), shot = null) {
  await idToken();
  const s = await getSession();
  const ts = new Date().toISOString();
  const noteId = crypto.randomUUID();
  const parsed = parseChecklist((content || "").slice(0, 10000));
  const fields = {
    ownerId: s.uid, ownerEmail: s.email, ownerName: s.name,
    content: parsed.content || (shot ? "Screenshot" : ""), note_date: noteDate, status: "open",
    created_at: ts, updated_at: ts, edited_at: null, completed_at: null,
    original_date: null, times_moved: 0, sharedWith: [], order: Date.now(),
  };
  if (parsed.checklist.length) fields.checklist = parsed.checklist;
  if (shot) {
    const shotId = crypto.randomUUID();
    await api("POST", `/qn_attachments?documentId=${shotId}`, {
      fields: encFields({
        ownerId: s.uid, noteId, mime: "image/jpeg", data: shot.full.split(",")[1],
        width: shot.width, height: shot.height, created_at: ts,
      }),
    });
    fields.attachment = { id: shotId, kind: "screenshot", width: shot.width, height: shot.height, thumb: shot.thumb };
  }
  const doc = await api("POST", `/${CONFIG.collection}?documentId=${noteId}`, { fields: encFields(fields) });
  countNoteCreated(s.uid);
  return fromDoc(doc);
}

/** My notes on a day plus notes shared with me on that day, in priority order. */
export async function notesOn(day) {
  await idToken();
  const s = await getSession();
  const query = (where) => api("POST", ":runQuery", { structuredQuery: { from: [{ collectionId: CONFIG.collection }], where } });
  const eq = (path, value) => ({ fieldFilter: { field: { fieldPath: path }, op: "EQUAL", value: enc(value) } });
  const [own, shared] = await Promise.all([
    query({ compositeFilter: { op: "AND", filters: [eq("ownerId", s.uid), eq("note_date", day)] } }),
    s.email
      ? query({ fieldFilter: { field: { fieldPath: "sharedWith" }, op: "ARRAY_CONTAINS", value: enc(s.email) } })
      : [],
  ]);
  const byId = new Map();
  for (const row of [...own, ...shared]) {
    if (!row.document) continue;
    const note = fromDoc(row.document);
    if (note.note_date === day && !note.deleted_at) byId.set(note.id, note); // skip notes in Trash
  }
  return [...byId.values()].sort((a, b) => rank(a) - rank(b));
}

// ---------- user profile ----------

const PROFILE_EVERY = 6 * 60 * 60 * 1000; // refresh at most every 6 hours

/** Saves who is using the extension to users/{uid}, touching only this extension's entry under `clients`. */
export async function recordUser({ force = false } = {}) {
  const { profileSavedAt = 0 } = await chrome.storage.local.get("profileSavedAt");
  if (!force && Date.now() - profileSavedAt < PROFILE_EVERY) return;
  const token = await idToken();
  const s = await getSession();

  // sign-up date and providers come from the account itself
  const lookup = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=${CONFIG.apiKey}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ idToken: token }),
  }).then((r) => (r.ok ? r.json() : null)).catch(() => null);
  const account = lookup?.users?.[0] || {};

  const now = new Date();
  const fields = {
    uid: s.uid,
    email: s.email,
    displayName: account.displayName || s.name || "",
    photoURL: account.photoUrl || s.photo || "",
    lastSeenAt: now,
    locale: navigator.language || "",
    timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone || "",
    clients: { chrome: { lastSeenAt: now, version: chrome.runtime.getManifest().version, userAgent: navigator.userAgent.slice(0, 300) } },
  };
  if (account.createdAt) fields.createdAt = new Date(Number(account.createdAt));
  if (account.lastLoginAt) fields.lastSignInAt = new Date(Number(account.lastLoginAt));
  if (account.providerUserInfo) fields.providers = account.providerUserInfo.map((p) => p.providerId);

  const mask = [...Object.keys(fields).filter((k) => k !== "clients"), "clients.chrome"]
    .map((f) => `updateMask.fieldPaths=${encodeURIComponent(f)}`).join("&");
  await api("PATCH", `/users/${s.uid}?${mask}`, { fields: encFields(fields) });
  await chrome.storage.local.set({ profileSavedAt: Date.now() });
}

export async function setStatus(note, status) {
  const ts = new Date().toISOString();
  const fields = { status, completed_at: status === "done" ? ts : null, updated_at: ts };
  const mask = Object.keys(fields).map((f) => `updateMask.fieldPaths=${f}`).join("&");
  await api("PATCH", `/${CONFIG.collection}/${note.id}?${mask}`, { fields: encFields(fields) });
}
